import {GameSession,InteractionState} from './session.js';
import {screenMarkup,catalogCards} from './screens.js';
import {CONTENT} from './catalog.js';
import {Game} from './engine.js';
import {baseFunding} from './protocol.js';
import {Battlefield} from './renderer.js';
import {OP,OPERATORS,CLASSES,ALLIANCES,STRATEGIES,DECISIONS,MAPS,DIFFICULTIES,EQ,SP,ROMAN,ENEMIES,traitText} from './data.js';

const STORAGE='garrison-protocol-v1';
const $=id=>document.getElementById(id);
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let incompatibleSave=false,expiredSave=false,suspensionExpiresAt=null;
let game=new Game(),selected=null,speed=1,paused=false,sound=false,modal=null,toastTimer,storageOK=true,audioContext=null,lastSound=0,modalFocus=null,finishedShown=false;
try{const raw=localStorage.getItem(STORAGE);if(raw){const parsed=JSON.parse(raw),envelope=parsed.saveVersion===2?parsed:{state:raw,expiresAt:null};suspensionExpiresAt=envelope.expiresAt;if(suspensionExpiresAt!==null&&Date.now()>=suspensionExpiresAt){localStorage.setItem('garrison-expired-save-backup',raw);expiredSave=true;suspensionExpiresAt=null;}else{const restored=Game.restore(envelope.state);if(restored){game=restored;paused=game.s.phase==='battle';}else{localStorage.setItem('garrison-incompatible-save-backup',raw);incompatibleSave=true;}}}sound=localStorage.getItem('garrison-sound')==='1';}catch{storageOK=false;}

let session=new GameSession(game,CONTENT);const interaction=new InteractionState();let screen='home',catalogQuery='',catalogProfession='all',screenOptions={};
const icons={
 shield:'<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M12 2 21 6v7l-9 9-9-9V6z"/><path d="m7 10 5-5 5 5-5 9z"/></svg>',
 full:'<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M8 3H3v5M16 3h5v5M21 16v5h-5M3 16v5h5"/></svg>',
 sound:'<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="m11 4-6 5H2v6h3l6 5zM15 8c4 3 4 5 0 8M18 4c7 5 7 11 0 16"/></svg>',
 mute:'<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="m11 4-6 5H2v6h3l6 5zM16 9l6 6M22 9l-6 6"/></svg>'
};
$('app').innerHTML=`<section id="screen-root" class="screen-root"></section><main id="battle-screen" class="shell">
 <header class="topbar"><button class="home-button" data-act="home" aria-label="返回大厅">‹</button><div class="emblem" aria-hidden="true">${icons.shield}</div><div class="wordmark"><strong>罗德岛</strong><div class="eyebrow">RHODES ISLAND</div></div><div class="top-divider"></div><div class="mode-label">作战终端 <b>/ 联合防卫</b></div><span class="project-tag">FAN-MADE EDITION</span><nav class="top-actions" aria-label="终端菜单"><button class="text-btn" data-act="roster">物资调配</button><button class="text-btn" data-act="help">作战手册</button><button class="icon-button" id="sound-button" data-act="sound" aria-label="开启音效">${icons.mute}</button><button class="icon-button" data-act="fullscreen" aria-label="全屏">${icons.full}</button></nav></header>
 <section class="titlebar"><div><h1>卫戍协议<span class="orange">.</span></h1><div class="subtitle"><span class="orange">盟约</span><span class="slash">/</span><span class="en-title">GARRISON PROTOCOL</span><span id="difficulty-label">独立模拟</span></div></div><div class="stats" id="stats"></div></section>
 <section class="workspace" aria-label="作战区域">
  <aside class="alliances-panel"><div class="side-title">盟约联结 <span class="num" id="alliance-count">00</span></div><div class="alliance-list" id="alliances"></div><div class="strategy-note" id="strategy"></div></aside>
  <div class="field-panel"><div class="field-header"><strong id="map-name"></strong><div class="flex"><span class="small muted" id="deployment-count"></span><span class="phase-tag" id="phase"></span></div></div><div class="field-wrap"><div id="deployment-layer" hidden></div><canvas id="battlefield" tabindex="0" role="application" aria-label="战场棋盘。干员拖到地块后进入朝向选择，拖动朝向并松手放置。键盘方向键选地块，回车进入朝向选择，再按方向键与回车确认。"></canvas><div class="map-tools"><button data-act="paths" title="显示或隐藏敌人路线" aria-label="敌人路线" aria-pressed="true">⌁</button><button data-act="grid" title="显示或隐藏网格" aria-label="战场网格" aria-pressed="true">⊞</button></div><div id="board-overlay"></div><div class="board-hint" id="board-hint"></div></div><div class="field-footer"><div class="legend"><span><i></i>敌方入口</span><span><i class="blue"></i>防卫目标</span><span><i class="gray"></i>高台</span></div><div class="battle-actions" id="battle-actions"></div></div><div class="bench-head"><strong>整备区 <span class="num muted" id="bench-count">0 / 10</span></strong><span>选择地块 → 拖动朝向 → 确认放置</span></div><div class="bench" id="bench" aria-label="整备区"></div><div id="overflow"></div></div>
  <aside class="intel-panel"><div class="intel" id="intel"></div><div class="selected-panel" id="selected-panel" hidden></div><div class="event-log"><div class="side-title">作战记录 <span class="num">LIVE LOG</span></div><div class="log-list" id="log"></div></div><div class="start-area" id="start-area"></div></aside>
 </section>
 <section class="supply" aria-label="调度中心"><div class="supply-header"><div class="supply-title"><div class="level-badge num" id="level">I</div><div><strong>调度中心</strong><div class="eyebrow">OPERATOR DISPATCH</div></div></div><div class="supply-controls" id="shop-controls"></div></div><div class="shop" id="shop"></div><div class="shop-note"><span>3 名初始干员 → 1 名精锐 + 晋升调配特许</span><span id="economy-note"></span></div></section>
 <footer class="footer"><span>同人独立模拟 · 角色及图像版权归鹰角网络所有 <button class="text-btn small" data-act="about">版本说明</button></span><span>PRTS // DEFENSE SYSTEM <span class="orange">01.00</span></span></footer>
</main>`;
const field=new Battlefield($('battlefield'),game);
function showScreen(view,options={}){if(view==='battle'&&suspensionExpiresAt!==null&&Date.now()>=suspensionExpiresAt){toast('暂离存档已超过24小时，请开始新的模拟。');return;}if(screen==='battle'&&view!=='battle'&&['prep','battle','intermission'].includes(game.s.phase)){suspensionExpiresAt??=Date.now()+86400000;save();}if(view==='battle'){suspensionExpiresAt=null;save();}screen=view;screenOptions=options;cancelDeployment();if(view!=='battle'&&game.s.phase==='battle')paused=true;$('screen-root').hidden=view==='battle';$('battle-screen').hidden=view!=='battle';$('app').setAttribute('data-view',view);if(view!=='battle')$('screen-root').innerHTML=screenMarkup(view,game,{query:catalogQuery,profession:catalogProfession,...options});else{field.resize();render();} }
function send(type,...args){return session.send(type,...args);}
function cancelDeployment(){interaction.cancel();field.placement=null;$('deployment-layer').hidden=true;}
function renderDeployment(){const layer=$('deployment-layer');if(interaction.mode!=='direction'||!interaction.cell){layer.hidden=true;return;}const u=game.s.units.find(u=>u.uid===interaction.uid);if(!u||!game.canManage()){cancelDeployment();return;}field.placement={...u,x:interaction.cell.x,y:interaction.cell.y,dir:interaction.direction??u.dir};const p=field.point(interaction.cell.x,interaction.cell.y),bounds=canvas.getBoundingClientRect();layer.style.setProperty('--aim-x',(bounds.left+p.x)+'px');layer.style.setProperty('--aim-y',(bounds.top+p.y)+'px');if(!layer.hidden&&layer.firstElementChild){const compass=layer.querySelector('.direction-compass');compass.style.left=p.x+'px';compass.style.top=p.y+'px';layer.querySelector('.direction-center').textContent=interaction.direction===null?'✥':['→','↓','←','↑'][interaction.direction];for(const button of layer.querySelectorAll('[data-act=deploy-direction]'))button.classList.toggle('chosen',Number(button.dataset.value)===interaction.direction);layer.querySelector('[data-act=deploy-confirm]').disabled=interaction.direction===null;field.draw();return;}layer.hidden=false;layer.innerHTML=`<div class="direction-compass" style="left:${p.x}px;top:${p.y}px" role="dialog" aria-label="选择部署朝向"><div class="direction-diamond"></div><span class="direction-center">${interaction.direction===null?'✥':['→','↓','←','↑'][interaction.direction]}</span>${[0,1,2,3].map(d=>`<button data-act="deploy-direction" data-value="${d}" class="compass-arrow direction-${d} ${interaction.direction===d?'chosen':''}" aria-label="朝${['右','下','左','上'][d]}">${['→','↓','←','↑'][d]}</button>`).join('')}<div class="direction-caption">拖动选择朝向 · 松手确认<br><small>中心松手或点击暗处取消</small></div></div><div class="direction-actions"><button data-act="deploy-cancel">取消部署</button><button data-act="deploy-confirm" ${interaction.direction===null?'disabled':''}>确认放置</button></div>`;field.draw();}
function confirmDeployment(){const result=interaction.commit(session);if(result.ok){cancelDeployment();selected=null;render();}else{if(result.code==='STALE_PREVIEW')cancelDeployment();toast(result.message||'请先选择朝向。');}return result.ok;}
function commitDeployment(uid,x,y){interaction.select(uid,game.s.phase);const preview=interaction.lockPosition(session,x,y);if(!preview.ok){cancelDeployment();toast(preview.message||'无法部署至此位置。');return false;}if(interaction.requiresDirection){renderDeployment();return false;}return confirmDeployment();}

function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),3200);}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify({saveVersion:2,state:game.serialize(),expiresAt:suspensionExpiresAt}));}catch{if(storageOK){storageOK=false;toast('浏览器无法保存进度，请保持当前页面开启。');}}}
function beep(kind){if(!sound)return;const now=performance.now();if(kind==='hit'&&now-lastSound<180)return;lastSound=now;try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.connect(gain);gain.connect(audioContext.destination);osc.type=kind==='skill'?'sine':'triangle';const freq=kind==='skill'?640:kind==='leak'?130:kind==='merge'?850:kind==='enemyHit'?170:380;osc.frequency.setValueAtTime(freq,audioContext.currentTime);osc.frequency.exponentialRampToValueAtTime(freq*.55,audioContext.currentTime+.07);gain.gain.setValueAtTime(kind==='hit'?.008:.025,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.0001,audioContext.currentTime+.12);osc.start();osc.stop(audioContext.currentTime+.13);}catch{sound=false;}}
function bindGame(){game.onNotice=toast;game.onEffect=e=>{field.add(e);beep(e.type);};game.onChange=()=>{if(selected&&!game.s.units.some(u=>u.uid===selected)&&!game.s.items.some(e=>e.uid===selected))selected=null;save();render();};field.game=game;}
bindGame();
function unitCard(u,index){if(!u)return `<button class="bench-slot empty" disabled aria-label="空整备位 ${index+1}"></button>`;const item=u.kind!=='op',data=item?(EQ[u.id]||SP[u.id]):OP[u.id],equips=!item?u.equipment.length:0;return `<button class="bench-slot ${selected===u.uid?'selected':''}" data-act="select" data-uid="${u.uid}" draggable="false" aria-label="${esc(data.name)}${u.elite?' 精锐':''}${item?' 选择使用':' 选择部署'}" title="${esc(data.name)}${item?' · '+data.desc:' · '+CLASSES[data.cls].name}">${item?`<span class="item-glyph">${data.glyph}</span>`:`<img src="./assets/${u.id}-avatar.png" alt="">`}${u.elite?'<span class="elite-tag">精</span>':''}${equips?`<span class="equip-marker">${'◆'.repeat(equips)}</span>`:''}<span class="bench-label">${data.name}</span></button>`;}
function renderStats(){const s=game.s,b=s.battle;$('stats').innerHTML=`<div class="stat"><label>目标生命</label><strong>${s.hp.toString().padStart(2,'0')}<small> / ${s.maxHp}</small></strong><div class="health-track"><span style="width:${s.hp/s.maxHp*100}%"></span></div></div><div class="stat money"><label>调度资金</label><strong>${s.money.toString().padStart(2,'0')} <small>◆</small></strong></div><div class="stat enemies-stat"><label>${s.phase==='battle'?'本轮击倒':'部署位'}</label><strong>${s.phase==='battle'?b.kills:game.onField.length}<small> / ${s.phase==='battle'?b.total:s.cap}</small></strong></div><div class="stat round"><label>作战轮次</label><strong>${s.round.toString().padStart(2,'0')}<small> / ${s.hidden?'17':'16'}</small></strong></div>`;$('difficulty-label').textContent=`独立模拟 · ${DIFFICULTIES[s.difficulty].name}`;}
function renderAlliances(){const alliances=Object.values(game.allies()).sort((a,b)=>Number(b.active)-Number(a.active)||b.count-a.count||b.stacks-a.stacks);let list=alliances.filter(a=>a.count>0||a.stacks>0);if(list.length<6)list.push(...alliances.filter(a=>!list.includes(a)).slice(0,6-list.length));$('alliance-count').textContent=alliances.filter(a=>a.active).length.toString().padStart(2,'0');$('alliances').innerHTML=list.map(a=>`<button class="alliance ${a.active?'active':''}" data-act="alliance" data-id="${a.id}" title="${a.desc}"><span class="alliance-symbol">${a.symbol}</span><div><strong>${a.name}</strong><div class="alliance-bars">${Array.from({length:a.need},(_,i)=>`<i class="${i<a.count?'on':''}"></i>`).join('')}</div><p>${a.active?`${a.stacks} 层 · ${a.kind}`:a.stacks?`${a.stacks} 层 · 尚未激活`:a.kind}</p></div><span class="count">${a.count}<small style="font-size:11px">/${a.need}</small></span></button>`).join('');const st=game.strategy;$('strategy').innerHTML=`<div class="eyebrow">ACTIVE STRATEGY</div><strong class="gold">✧ ${st.name}</strong><p>${st.desc}</p>${game.s.decisions.length?`<p>${game.s.decisions.map(id=>DECISIONS.find(d=>d.id===id).name).join(' · ')}</p>`:''}`;}
function renderBoardUI(){const s=game.s,brief=s.phase==='briefing';$('map-name').innerHTML=`<span class="muted num">${game.map.code}</span>　${game.map.name}`;$('deployment-count').textContent=`${game.onField.length} / ${s.cap} 部署`;
 const phaseNames={briefing:'待命 / STANDBY',prep:'休整期 / PREPARATION',battle:paused?'已暂停 / PAUSED':'作战中 / IN COMBAT',intermission:'作战完成 / COMPLETE',finished:s.won?'模拟成功 / VICTORY':'模拟结束 / DEFEAT'};$('phase').textContent=phaseNames[s.phase];$('phase').className=`phase-tag ${s.phase==='battle'?'battle':''}`;
 $('board-overlay').innerHTML=brief?`<div class="field-overlay"><div class="briefing"><div class="eyebrow">INDEPENDENT DEFENSE SIMULATION</div><h2>防卫阵线，等待指令</h2><p>调配干员，构筑盟约。<br>在十六轮攻势中建立你的防线，迎击最终领袖。</p><button class="primary" data-act="setup">开始独立模拟　↗</button><div class="small muted" style="margin-top:14px">35 名干员 · 3 张战场 · 3 种难度</div></div></div>`:s.phase==='intermission'?`<div class="field-overlay" style="background:#0b14195c"><div class="briefing"><div class="eyebrow">ROUND ${s.round.toString().padStart(2,'0')} COMPLETE</div><h2 style="color:var(--cyan)">${s.lastResult.leaks?'防线坚守':'完美防卫'}</h2><p>击倒 ${s.lastResult.kills} 名敌人 · ${Math.round(s.lastResult.time)} 秒${s.lastResult.leaks?` · 流失 ${s.lastResult.leaks} 点生命`:''}${s.hidden?'<br>无损作战达成 · 隐秘核心已显现':''}</p><button class="primary" data-act="next">进入第 ${s.round+1} 轮休整　→</button></div></div>`:'';
 const chosen=game.s.units.find(u=>u.uid===selected),item=game.s.items.find(u=>u.uid===selected);$('board-hint').textContent=brief?'':s.phase==='battle'?'系统自动作战 · 技能与再部署自动执行':item?'选择一名干员以使用装备或晋升装置':chosen?`${OP[chosen.id].name} · 选定地块后拖动朝向确认 / Delete 出售`:'拖动整备区干员到地块，再拖动朝向确认';
 $('battle-actions').innerHTML=`<button data-act="pause" ${s.phase!=='battle'?'disabled':''} aria-label="${paused?'继续作战':'暂停作战'}">${paused?'▶':'Ⅱ'}</button>${[1,2,4].map(n=>`<button data-act="speed" data-value="${n}" class="${speed===n?'active':''}" aria-pressed="${speed===n}">${n}×</button>`).join('')}`;
 field.selection=selected;
}
function renderBench(){const hand=game.hand;$('bench-count').textContent=`${Math.min(10,hand.length)} / 10`;$('bench').innerHTML=Array.from({length:10},(_,i)=>unitCard(hand[i],i)).join('');$('overflow').innerHTML=hand.length>10?`<div class="overflow-warning">临时整备区：开战时清空，请及时处理。</div><div class="overflow-bench">${hand.slice(10).map((u,i)=>unitCard(u,i)).join('')}</div>`:'';}
function renderIntel(){const s=game.s,[name,type,count,waveNote]=game.wave,e=ENEMIES[type],enemyImg=e.icon==='heavy'?'defender':e.icon;
 $('intel').innerHTML=`<div class="intel-top">${s.phase==='battle'?'当前攻势':'下一轮情报'} <span class="num">/ ${s.round.toString().padStart(2,'0')}</span></div><h3>${name}</h3><div class="intel-sub">${s.round>=16?'领袖单位':e.name} · ${s.phase==='battle'?s.battle.total:count} ${s.round>=16?'目标':'单位'}</div><div class="enemy-strip">${Array.from({length:Math.min(4,count)},()=>`<div class="enemy-token"><img src="./assets/enemy-${enemyImg}.png" alt="${e.name}"></div>`).join('')}${count>4?`<span class="num muted" style="align-self:center">+${count-4}</span>`:''}</div><div class="threat">${e.boss?'▲ 领袖威胁':e.flying?'⌁ 空中单位':e.unblockable?'↯ 无法阻挡':e.def>500?'⬡ 重型装甲':e.arts?'◇ 法术攻击':'⚑ 地面攻势'}</div><div class="enemy-note">${waveNote}</div><div class="wave-track">${Array.from({length:s.hidden?17:16},(_,i)=>`<i class="${i+1<s.round?'done':i+1===s.round?'current':''}"></i>`).join('')}</div><div class="spread small muted" style="font-size:10px"><span>作战进程</span><span class="num">${s.round} / ${s.hidden?17:16}</span></div>`;
 const trial=s.battle?.benchmark,pendingTrial=s.phase==='prep'&&s.round>=16&&game.content.finalPhase?.kind==='training-dummy';
 if(trial||pendingTrial){const target=trial?s.battle.enemies.find(e=>e.trainingDummy):null,total=target?.damageLedger.total||s.benchmarkResult?.totalDamage||0,duration=trial?.duration??game.content.finalPhase.duration;$('intel').innerHTML=`<div class="intel-top">最终阶段 · 木桩替代</div><h3>无限血量木桩</h3><p class="benchmark-clock">${Math.max(0,Math.ceil(duration-(trial?.elapsedFrames||0)/30))} <small>秒</small></p><p>累计伤害</p><strong class="benchmark-total">${Math.round(total).toLocaleString()}</strong><p class="small muted">防御 0 · 法抗 0 · 不移动、不攻击<br>沿用原版 ${duration} 秒倒计时</p>`;}
 $('log').innerHTML=s.logs.slice(0,6).map(l=>`<div class="log-entry"><span class="num">${l.round.toString().padStart(2,'0')}</span><span>${l.text}</span></div>`).join('')||'<div class="log-entry">等待模拟指令。</div>';
 let action='start',label='准备完毕',note='资金会在开战时清零，请合理使用。',icon='▷';if(s.phase==='briefing'){action='setup';label='开始模拟';note='选择策略后进入休整期。';}if(s.phase==='battle'){action='pause';label=paused?'继续作战':'暂停作战';note='自动索敌 · 自动技能 · 自动再部署';icon=paused?'▷':'Ⅱ';}if(s.phase==='intermission'){action='next';label='继续休整';note=`进入第 ${s.round+1} 轮`;icon='→';}if(s.phase==='finished'){action='result';label='查看结算';note='本次模拟已结束。';icon='↗';}
 $('start-area').innerHTML=`<button class="primary" data-act="${action}"><span>${label}</span><span>${icon}</span></button><div class="note">${note}</div>${s.phase==='prep'?'<button data-act="benchmark" class="benchmark-button" title="木桩位于第6列第2行（F2），测试150秒">当前阵容木桩测试</button>':s.phase==='battle'&&s.battle?.benchmark?'<button data-act="end-benchmark" class="benchmark-button">结束测试并统计伤害</button>':''}`;
}
function renderSelected(){const u=game.s.units.find(u=>u.uid===selected),item=game.s.items.find(i=>i.uid===selected),panel=$('selected-panel');if(!u&&!item){panel.hidden=true;return;}panel.hidden=false;
 if(item){const d=EQ[item.id]||SP[item.id];panel.innerHTML=`<div class="spread"><h3>${d.name}</h3><button class="text-btn" data-act="deselect" aria-label="取消选择">×</button></div><p>${d.desc}</p><p class="gold">${item.kind==='equipment'?'点击战场或整备区中的干员装备。':item.id==='elite'?'点击一名初始干员晋升。':''}</p><div class="unit-actions">${item.kind==='spell'&&item.id!=='elite'?'<button data-act="use-spell">立即使用</button>':''}<button data-act="sell">销毁</button></div>`;return;}
 const o=OP[u.id],a=game.attributes(u),bu=game.s.battle?.units.find(b=>b.uid===u.uid),sk=game.skill(u);panel.innerHTML=`<div class="spread"><h3>${o.name} ${u.elite?'<span class="gold small">精锐</span>':''}</h3><button class="text-btn" data-act="deselect" aria-label="取消选择">×</button></div><div class="small muted">${CLASSES[o.cls].glyph} ${CLASSES[o.cls].name} · ${ROMAN[o.tier]} 阶 · 阻挡 ${a.block}</div><div class="stat-grid"><div>攻击<b>${Math.round(a.atk)}</b></div><div>防御<b>${Math.round(a.def)}</b></div><div>生命<b>${Math.round(bu?.hp??a.hp)}</b></div></div><div class="small gold">${sk.name}${bu?` · ${bu.active>0?'生效中':`${Math.floor(bu.sp)}/${sk.sp} SP`}`:''}</div><p>${sk.desc}</p>${u.equipment.length?`<div class="equipment-row">${u.equipment.map(e=>`<span title="${EQ[e.id].desc}">${EQ[e.id].glyph} ${e.elite?'进阶 ':''}${EQ[e.id].name}</span>`).join('')}</div>`:''}${game.s.phase==='prep'?`<div class="direction" aria-label="部署朝向">${['→','↓','←','↑'].map((d,i)=>`<button data-act="direction" data-value="${i}" class="${u.dir===i?'active':''}" aria-label="面向${['右','下','左','上'][i]}">${d}</button>`).join('')}</div><div class="unit-actions">${u.x!==null?'<button data-act="withdraw">撤回整备</button>':''}<button data-act="sell">出售 <span class="gold">+1 ◆</span></button><button data-act="operator" data-id="${o.id}">资料</button></div>`:`<button class="text-btn small" data-act="operator" data-id="${o.id}">干员资料 ↗</button>`}`;
}
function shopCard(offer,i){if(!offer)return `<button class="shop-card sold" disabled aria-label="空调度栏"><b>⌘</b><span>${game.s.phase==='briefing'?'等待接入':game.s.phase==='battle'?'作战中':'已调配'}</span></button>`;const op=offer.kind==='op',d=op?OP[offer.id]:EQ[offer.id],owned=op?game.s.units.filter(u=>u.id===d.id&&!u.elite).length:0;return `<button class="shop-card ${owned?'duplicate':''}" data-act="buy" data-index="${i}" ${!game.canManage()?'disabled':''} title="${op?d.name+' · '+d.skills[0].desc:d.desc}" aria-label="招募${d.name}，消耗${game.cost(offer)}资金">${op?`<img src="./assets/${d.id}-portrait.png" alt="">`:`<span class="equip-visual">${d.glyph}</span>`}<span class="tier">${ROMAN[d.tier]}</span><span class="cost">${game.cost(offer)}</span><span class="class-icon">${op?CLASSES[d.cls].glyph:'◈'}</span><div class="shop-info"><h3>${d.name}</h3><p>${op?`${CLASSES[d.cls].name} · ${d.placement==='melee'?'近战':d.placement==='either'?'全地形':'远程'}`:'战术装备'}</p><div class="synergy-label">${op?d.alliances.map(a=>ALLIANCES[a].name).join(' / '):d.desc.split('；')[0].split(' / ')[0]}</div></div>${owned?`<span class="owned">${owned} / 3</span>`:''}</button>`;}
function renderShop(){const s=game.s;$('level').textContent=ROMAN[s.level];$('shop-controls').innerHTML=`<button data-act="upgrade" ${!game.canManage()||s.level>=6?'disabled':''} title="升级解锁更高阶干员，每回合升级费用减1">升级 <span class="num">${s.level>=6?'MAX':`${game.upgradeCost} ◆`}</span></button><button data-act="refresh" ${!game.canManage()?'disabled':''} title="R 刷新调度中心">↻ 刷新 <span class="num">${s.freeRefresh>0?'免费':'1 ◆'}</span></button><button class="${s.locked?'locked':''}" data-act="lock" ${!game.canManage()?'disabled':''} aria-pressed="${s.locked}" title="保留本轮剩余物资到下个休整期">${s.locked?'❄ 已冻结':'❄ 冻结'}</button>`;$('shop').innerHTML=Array.from({length:Math.max(6,game.shopSlots)},(_,i)=>shopCard(s.shop[i],i)).join('');$('economy-note').textContent=s.phase==='briefing'?'招募按等阶 2 / 3 / 4 ◆ · 出售 +1 ◆':`基础资金 ${s.baseFunds??baseFunding(s.round)} ◆ · 剩余 ${s.money} ◆ · 开战时清零`;$('sound-button').innerHTML=sound?icons.sound:icons.mute;$('sound-button').setAttribute('aria-label',sound?'关闭音效':'开启音效');}
function render(){if(interaction.mode==='direction'&&(interaction.phase!==game.s.phase||interaction.revision!==session.revision))cancelDeployment();renderStats();renderAlliances();renderBoardUI();renderBench();renderIntel();renderSelected();renderShop();field.draw();syncForcedModal();}
function header(title,eyebrow,subtitle='',closable=true){return `<div class="dialog-header"><div><div class="eyebrow">${eyebrow}</div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${closable?'<button class="icon-button" data-act="close" aria-label="关闭">×</button>':''}</div>`;}
function openModal(type,data={}){modalFocus=document.activeElement;modal={type,...data};renderModal();if(!$('dialog').open)$('dialog').showModal();}
function closeModal(force=false){if(!force&&['promotion','decision','replace'].includes(modal?.type))return;modal=null;$('dialog').close();if(modalFocus?.isConnected)modalFocus.focus();}
function syncForcedModal(){if(game.s.rewardOffers){if(modal?.type!=='promotion')openModal('promotion');else renderModal();}else if(game.s.decisionOffers){if(modal?.type!=='decision')openModal('decision');else renderModal();}else if(['promotion','decision'].includes(modal?.type))closeModal(true);if(game.s.phase==='finished'&&!modal&&!finishedShown){finishedShown=true;if(game.s.benchmarkResult){const message='木桩测试结束，总伤害 '+Math.round(game.s.benchmarkResult.totalDamage).toLocaleString();toast(message);if(sound&&window.speechSynthesis&&window.SpeechSynthesisUtterance){try{const speech=new window.SpeechSynthesisUtterance(message);speech.lang='zh-CN';window.speechSynthesis.speak(speech);}catch{}}}openModal('result');}}
