 if(modal.type==='help')html=header('作战手册','FIELD OPERATIONS MANUAL','先规划防线，再让干员自动执行作战。')+`<div class="handbook-grid"><section><h3>01 / 招募与调度</h3><p>干员招募消耗 3 资金，出售返还 1 资金。升级解锁更高阶干员；每个回合升级费用减 1。刷新消耗 1 资金，冻结可保留剩余物资。<b class="gold">资金不会跨回合保留，开战时清零。</b></p></section><section><h3>02 / 部署与方向</h3><p>点击整备区干员，再点地块部署，也可拖动到战场。近战放地面，远程可放地面或高台。选择场上干员查看射界，使用方向按钮或 <span class="key">Q</span> 旋转。初始最多部署 8 人，场上可交换位置。</p></section><section><h3>03 / 精锐与装备</h3><p>获得 3 名同名初始干员后自动合成精锐，并免费三选一高阶干员。精锐只有一档。2 件同名初始装备自动合为进阶装备。每名干员可装 2 件；装备在干员出售或合成时退回。</p></section><section><h3>04 / 构筑盟约</h3><p>部署足够数量的不同干员即可激活盟约，同名干员只计数一次。干员特质通过招募、刷新、回合或战斗事件积累层数。点击盟约可查看当前效果，精锐特质的层数收益翻倍。</p></section><section><h3>05 / 自动战斗</h3><p>作战中不能调整布阵。干员自动索敌、治疗、释放技能；被击倒后等待冷却及部署费用，随后原位返回。漏怪扣除目标生命。物理伤害受防御影响，法术受法抗影响，真实伤害无视两者。</p></section><section><h3>06 / 长期防卫</h3><p>第 4、8、12 轮后选择额外策略。第 16 轮挑战泥岩；险境或绝境无漏怪击败领袖后，进入第 17 轮隐秘核心。战斗超时后敌方持续强化，领袖回合还会持续扣除目标生命。</p></section></div><div class="line"></div><p class="muted small"><span class="key">Space</span> 开战 / 暂停　<span class="key">R</span> 刷新　<span class="key">E</span> 升级　<span class="key">Q</span> 转向　<span class="key">Delete</span> 出售　<span class="key">Esc</span> 取消选择</p><div class="dialog-bottom"><button data-act="about">查看本版范围与规则来源</button><button class="primary" data-act="close">返回阵地</button></div>`;
 if(modal.type==='about')html=header('同人模拟 · 版本说明','FAN-MADE / VERSION 1.0')+`<div class="handbook-grid"><section><h3>本版可玩内容</h3><p>35 名干员、6 个调度等阶、15 种盟约、8 种装备、10 种局内策略、3 张自制地图，以及 16 轮作战和条件触发的隐秘核心。包括三合一、晋升招募、装备合成、资金清零、自动技能与再部署。</p></section><section><h3>与原版的差异</h3><p>这是独立运行的同人单人版本。干员属性、部分技能与盟约效果、敌人编排和地图为适配网页重制的数值与实现。未实现原版全部干员、历期内容、官方账号成长与奖励系统，也不包含四人在线同盟模拟。</p></section></div><div class="note-box">本版提供完整的自制单人对局流程，不等同于原版全内容或逐项数值复刻。不会连接《明日方舟》官方账号；进度仅保存在当前浏览器。</div><p class="muted" style="font-size:13px;line-height:1.9">规则核对：<a href="https://prts.wiki/w/卫戍协议" target="_blank" rel="noopener">PRTS 卫戍协议</a>、<a href="https://prts.wiki/w/卫戍协议/帮助" target="_blank" rel="noopener">操作与规则帮助</a>。角色图像来自 <a href="https://github.com/ArknightsAssets/ArknightsAssets2" target="_blank" rel="noopener">ArknightsAssets2 资料镜像</a>，版权属于鹰角网络及其关联公司。本作非官方产品。</p><div class="dialog-bottom"><button data-act="reset">重新开始模拟</button><button class="primary" data-act="close">返回阵地</button></div>`;
 if(modal.type==='roster')html=header('物资调配处','OPERATOR ROSTER',`当前模拟池 · ${OPERATORS.length} 名干员。等阶固定；点击干员查看技能与特质。`)+`<div class="roster-grid">${OPERATORS.map(o=>`<button class="roster-card" data-act="operator" data-id="${o.id}"><img src="./assets/${o.id}-avatar.png" alt=""><span class="tier num">${ROMAN[o.tier]}</span><strong>${o.name}</strong></button>`).join('')}</div>`;
 if(modal.type==='operator'){const o=OP[modal.id];html=header('干员档案','OPERATOR PROFILE')+`<div class="focus-details"><img src="./assets/${o.id}-portrait.png" alt="${o.name}"><div><h3>${o.name}</h3><p>${ROMAN[o.tier]} 阶 · ${CLASSES[o.cls].name} · ${o.placement==='melee'?'近战地面部署':'远程 / 可部署地面'}</p><p>${o.alliances.map(id=>`<span class="tag">${ALLIANCES[id].name}</span>`).join('')}</p><p class="gold">生命 ${o.hp}　攻击 ${o.atk}　防御 ${o.def}<br>法抗 ${o.res}　阻挡 ${o.block}</p><div class="line"></div><strong class="gold">协议特质</strong><p>${traitText(o)}</p>${o.skills.map((sk,i)=>`<div style="margin:12px 0"><strong>${sk.name}</strong> <span class="small muted">${sk.sp} SP</span><p>${sk.desc}</p>${o.skills.length>1?`<button data-act="skill-pref" data-id="${o.id}" data-value="${i}" ${game.s.phase!=='briefing'?'disabled':''} class="${(s.skillPrefs[o.id]||0)===i?'primary':''}">${(s.skillPrefs[o.id]||0)===i?'当前携带':'携带此技能'}</button>`:''}</div>`).join('')}</div></div><div class="dialog-bottom"><span class="small muted">本版重制参数；精锐基础属性 × 1.8。</span><button data-act="roster">返回物资调配</button></div>`;}
 if(modal.type==='alliance'){const a=game.allies()[modal.id],members=OPERATORS.filter(o=>o.alliances.includes(a.id));html=header(`${a.symbol} ${a.name}`,'ALLIANCE INTELLIGENCE',`${a.count} / ${a.need} 名不同干员 · ${a.active?'已激活':'未激活'} · ${a.stacks} 层`)+`<p style="font-size:16px;line-height:1.9">${a.desc}</p><p class="muted small">同名干员只计 1 名。盟约被暂时关闭后保留层数，重新满足人数条件即可恢复效果。</p><div class="line"></div><div class="roster-grid">${members.map(o=>`<button class="roster-card" data-act="operator" data-id="${o.id}"><img src="./assets/${o.id}-avatar.png" alt=""><span class="tier num">${ROMAN[o.tier]}</span><strong>${o.name}</strong></button>`).join('')}</div>`;}
 if(modal.type==='replace'){const u=game.s.units.find(u=>u.uid===modal.target);html=header('替换已装备物资','EQUIPMENT REPLACEMENT','该干员已持有两件装备。选择一件替换，旧装备将销毁。',false)+`<div class="options" style="grid-template-columns:1fr 1fr">${u.equipment.map((e,i)=>`<button class="option" data-act="replace" data-index="${i}"><div class="option-symbol">${EQ[e.id].glyph}</div><h3>${EQ[e.id].name}</h3><p>${e.elite?'进阶 · ':''}${EQ[e.id].desc}</p><div class="option-tag">销毁并替换</div></button>`).join('')}</div><div class="dialog-bottom"><button data-act="cancel-replace">取消装备</button></div>`;}
 if(modal.type==='result'&&s.benchmarkResult){const r=s.benchmarkResult;html=header('木桩测试完成','DAMAGE REPORT')+`<div class="benchmark-report"><p>木桩总伤害</p><strong class="benchmark-total">${Math.round(r.totalDamage).toLocaleString()}</strong><p>${r.elapsed.toFixed(2)} 秒 · DPS ${r.dps.toFixed(2)} · ${r.reason==='timeout'?'倒计时结束':'手动结束'}</p><div class="damage-chart">${r.units.map(u=>`<div class="damage-row"><span>${esc(OP[u.id]?.name||'其他来源')}</span><b>${Math.round(u.damage).toLocaleString()}</b></div>`).join('')||'<p>本次没有造成伤害。</p>'}</div><div class="dialog-bottom"><button data-act="new-game" class="primary">重新开始</button></div></div>`;}
 if(modal.type==='result'&&!s.benchmarkResult){const st=s.stats,damage=Object.entries(st.damage).sort((a,b)=>b[1]-a[1]).slice(0,8),max=damage[0]?.[1]||1;html=header('模拟结算','AFTER ACTION REPORT')+`<div class="result-head ${s.won?'':'failure'}"><div class="eyebrow">${s.won?'GARRISON PROTOCOL FULFILLED':'DEFENSE SIMULATION TERMINATED'}</div><h2>${s.won?'协议已履行':'模拟已结束'}</h2><p class="muted">${DIFFICULTIES[s.difficulty].name} / ${game.map.name}${s.hidden?' / 隐秘核心':''}</p></div><div class="result-stats"><div><b>${st.rounds}</b><span>完成轮次</span></div><div><b>${st.kills}</b><span>累计击倒</span></div><div><b>${st.merges}</b><span>精锐晋升</span></div><div><b>${s.hp}</b><span>剩余生命</span></div></div><div class="damage-chart"><div class="side-title">输出贡献 <span class="num">TOTAL DAMAGE</span></div>${damage.length?damage.map(([id,d])=>`<div class="damage-row"><span>${OP[id].name}</span><div class="damage-bar"><i style="width:${d/max*100}%"></i></div><b>${Math.round(d).toLocaleString()}</b></div>`).join(''):'<p class="muted small">本次模拟未产生伤害记录。</p>'}</div><div class="dialog-bottom"><p>作战用时 ${Math.floor(st.time/60)} 分 ${Math.floor(st.time%60)} 秒<br>总招募 ${st.bought} 名 · 漏失生命 ${st.leaks}</p><button class="primary" data-act="new-game">再次模拟　↗</button></div>`;}
 if(modal.type==='reset')html=header('重新建立协议？','RESTART SIMULATION','当前对局进度会被新的模拟替换。')+`<div class="dialog-bottom"><button data-act="close">继续当前模拟</button><button class="primary" data-act="new-game">重新开始</button></div>`;
 $('dialog-content').innerHTML=`<div class="dialog-inner">${html}</div>`;
