function setSelected(uid){const item=game.s.items.find(e=>e.uid===selected);if(item&&game.s.units.some(u=>u.uid===uid)){const out=item.kind==='equipment'?send('equip',item.uid,uid):send('spell',item.uid,uid);if(out.code==='REPLACE_REQUIRED'){openModal('replace',{item:item.uid,target:uid});return;}if(out.ok)selected=uid;render();return;}
 selected=uid;renderSelected();renderBench();renderBoardUI();}
function newGame(){closeModal(true);const prefs={...game.s.skillPrefs};game=new Game();suspensionExpiresAt=null;game.s.skillPrefs=prefs;session=new GameSession(game,CONTENT);selected=null;paused=false;finishedShown=false;bindGame();field.clear();render();save();showScreen('setup');}
async function action(button){const act=button.dataset.act,id=button.dataset.id,value=Number(button.dataset.value),uid=Number(button.dataset.uid),index=Number(button.dataset.index);
 switch(act){
 case 'setup':showScreen('setup');break;
 case 'home':closeModal(true);showScreen('home');break;
 case 'return-battle':showScreen('battle');break;
 case 'database':showScreen('database');break;
 case 'catalog-detail':showScreen('catalog-detail',{id});break;
 case 'catalog-filter':catalogProfession=id;showScreen('database');break;
 case 'season':showScreen('season');break;
 case 'season-tab':showScreen('season',{tab:id});break;
 case 'room':showScreen('room');break;
 case 'briefing':showScreen('briefing');break;
 case 'roster':showScreen('roster');break;
 case 'difficulty':send('preferences',{difficulty:id});showScreen(screen);break;
 case 'map':send('preferences',{map:value});field.clear();showScreen(screen);break;
 case 'strategy':send('preferences',{strategy:id});showScreen(screen);break;
 case 'deploy-direction':interaction.setDirection(value);renderDeployment();break;
 case 'deploy-confirm':confirmDeployment();break;
 case 'deploy-cancel':cancelDeployment();selected=null;render();break;
 case 'begin':closeModal(true);send('begin');showScreen('battle');toast('先招募一名近战干员，点击整备区，再部署到北侧通道。');break;
 case 'buy':send('buy',index);break;
 case 'select':setSelected(uid);break;
 case 'deselect':selected=null;render();break;
 case 'upgrade':send('upgrade');break;
 case 'refresh':send('refresh');break;
 case 'lock':send('lock');break;
 case 'start':if(game.s.money>=3&&!modal)openSpendReminder();else {paused=false;send('start');}break;
 case 'confirm-start':closeModal(true);paused=false;send('start');break;
 case 'benchmark':selected=null;paused=false;send('benchmark');break;
 case 'end-benchmark':send('endBenchmark');break;
 case 'pause':if(game.s.phase==='battle'){paused=!paused;renderBoardUI();renderIntel();}break;
 case 'speed':speed=value;renderBoardUI();break;
 case 'next':selected=null;field.clear();send('next');break;
 case 'promotion':send('promotion',index);break;
 case 'decision':send('decision',id);break;
 case 'direction':send('turn',selected,value);break;
 case 'withdraw':send('withdraw',selected);break;
 case 'sell':send('sell',selected);selected=null;render();break;
 case 'use-spell':send('spell',selected);selected=null;render();break;
 case 'replace':{const {item,target}=modal;closeModal(true);send('equip',item,target,index);selected=target;render();break;}
 case 'cancel-replace':closeModal(true);break;
 case 'help':case 'about':case 'result':case 'reset':openModal(act);break;
 case 'operator':openModal('operator',{id});break;
 case 'alliance':openModal('alliance',{id});break;
 case 'skill-pref':if(game.s.phase==='briefing'&&OP[id]?.skills[value]){send('skillPreference',id,value);save();renderModal();if(screen==='roster')showScreen('roster');}break;
 case 'new-game':newGame();break;
 case 'close':closeModal();break;
 case 'sound':sound=!sound;try{localStorage.setItem('garrison-sound',sound?'1':'0');}catch{}beep('skill');renderShop();break;
 case 'fullscreen':try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('当前浏览器不支持全屏，请使用浏览器全屏功能。');}break;
 case 'paths':field.paths=!field.paths;button.setAttribute('aria-pressed',String(field.paths));break;
 case 'grid':field.grid=!field.grid;button.setAttribute('aria-pressed',String(field.grid));break;
 }
}
function openSpendReminder(){if(!game.onField.length){game.notify('请先部署干员，再开始作战。');return;}openModal('spend');$('dialog-content').innerHTML=`<div class="dialog-inner">${header('开始本轮作战？','READY CHECK',`还有 ${game.s.money} 点资金，开战后将清零。`)}<div class="dialog-bottom"><button data-act="close">继续整备</button><button class="primary" data-act="confirm-start">准备完毕，开始作战</button></div></div>`;}
document.addEventListener('click',e=>{if(e.pointerType==='touch'||performance.now()<suppressClickUntil)return;const button=e.target.closest('button[data-act]');if(button&&!button.disabled)action(button);});
$('dialog').addEventListener('cancel',e=>{e.preventDefault();closeModal();});
$('dialog').addEventListener('click',e=>{if(e.target===$('dialog')){const r=$('dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});

let pointerStart=null,handDrag=null,directionDrag=null,suppressClickUntil=0,keyboardCell={x:4,y:1};
const canvas=$('battlefield');
const inCanvas=(x,y)=>{const r=canvas.getBoundingClientRect();return x>=r.left&&x<=r.right&&y>=r.top&&y<=r.bottom;};
canvas.addEventListener('pointermove',e=>{if(interaction.mode==='direction')return;field.hover=field.cell(e.clientX,e.clientY);});canvas.addEventListener('pointerleave',()=>{field.hover=null;});
canvas.addEventListener('pointerdown',e=>{if(e.button!==0||interaction.mode==='direction')return;const cell=field.cell(e.clientX,e.clientY),unit=game.s.units.find(u=>u.x===cell.x&&u.y===cell.y);pointerStart={cell,unit:unit?.uid,px:e.clientX,py:e.clientY};canvas.setPointerCapture(e.pointerId);});
canvas.addEventListener('pointerup',e=>{const cell=field.cell(e.clientX,e.clientY);if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);const start=pointerStart;pointerStart=null;if(!start||interaction.mode==='direction')return;const moved=Math.hypot(start.px-e.clientX,start.py-e.clientY)>9,unit=game.s.units.find(u=>u.x===cell.x&&u.y===cell.y);
 if(moved&&start.unit&&game.canManage()){selected=start.unit;commitDeployment(start.unit,cell.x,cell.y);return;}
 const item=game.s.items.find(i=>i.uid===selected);if(item&&unit){setSelected(unit.uid);return;}
 if(selected&&game.canManage()&&game.s.units.some(u=>u.uid===selected)){if(unit?.uid===selected){renderSelected();return;}commitDeployment(selected,cell.x,cell.y);return;}
 if(unit)setSelected(unit.uid);else{selected=null;render();}
});
canvas.addEventListener('pointercancel',()=>{pointerStart=null;cancelDeployment();});
document.addEventListener('pointerdown',e=>{if(e.isPrimary===false)return;suppressClickUntil=0;const button=e.target.closest('[data-act="select"]');if(!button||!game.canManage()||interaction.mode==='direction')return;const uid=Number(button.dataset.uid);if(!game.s.units.some(u=>u.uid===uid))return;handDrag={uid,pointerId:e.pointerId,x:e.clientX,y:e.clientY,moved:false,button};button.setPointerCapture?.(e.pointerId);});
document.addEventListener('pointermove',e=>{if(!handDrag||handDrag.pointerId!==e.pointerId)return;if(Math.hypot(e.clientX-handDrag.x,e.clientY-handDrag.y)<8&&!handDrag.moved)return;handDrag.moved=true;selected=handDrag.uid;const cell=field.cell(e.clientX,e.clientY),u=game.s.units.find(u=>u.uid===selected);if(!u){handDrag=null;cancelDeployment();return;}field.hover=cell;field.placement=inCanvas(e.clientX,e.clientY)&&game.canPlace(u,cell.x,cell.y)?{...u,x:cell.x,y:cell.y}:null;field.draw();e.preventDefault();});
document.addEventListener('pointerup',e=>{if(!handDrag||handDrag.pointerId!==e.pointerId)return;const drag=handDrag;handDrag=null;if(!drag.moved)return;suppressClickUntil=performance.now()+250;field.placement=null;if(inCanvas(e.clientX,e.clientY)){const cell=field.cell(e.clientX,e.clientY);commitDeployment(drag.uid,cell.x,cell.y);}else cancelDeployment();});
document.addEventListener('pointercancel',()=>{handDrag=null;directionDrag=null;cancelDeployment();});
$('deployment-layer').addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;const r=canvas.getBoundingClientRect(),p=field.point(interaction.cell.x,interaction.cell.y),x=r.left+p.x,y=r.top+p.y;if(Math.hypot(e.clientX-x,e.clientY-y)>105){cancelDeployment();selected=null;render();return;}directionDrag={pointerId:e.pointerId,x,y};$('deployment-layer').setPointerCapture(e.pointerId);});
$('deployment-layer').addEventListener('pointermove',e=>{if(!directionDrag||e.pointerId!==directionDrag.pointerId)return;interaction.aim(e.clientX-directionDrag.x,e.clientY-directionDrag.y);renderDeployment();e.preventDefault();});
$('deployment-layer').addEventListener('pointerup',e=>{if(!directionDrag||e.pointerId!==directionDrag.pointerId)return;interaction.aim(e.clientX-directionDrag.x,e.clientY-directionDrag.y);directionDrag=null;suppressClickUntil=performance.now()+150;if(interaction.direction===null){cancelDeployment();selected=null;render();}else confirmDeployment();});
document.addEventListener('input',e=>{if(e.target.id==='season-search'){const term=e.target.value.trim().toLowerCase();for(const entry of document.querySelectorAll('.season-content>.season-entry'))entry.hidden=!entry.textContent.toLowerCase().includes(term);}if(e.target.id==='catalog-search'){catalogQuery=e.target.value;$('catalog-results').innerHTML=catalogCards(catalogQuery,catalogProfession);}});
// Touch buttons use pointer taps directly; compatibility clicks may be suppressed after a drag.
let touchButton=null;
document.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch'||e.isPrimary===false)return;const button=e.target.closest('button[data-act]');touchButton=button&&!button.disabled?{button,id:e.pointerId,x:e.clientX,y:e.clientY}:null;});
document.addEventListener('pointermove',e=>{if(touchButton&&touchButton.id===e.pointerId&&Math.hypot(e.clientX-touchButton.x,e.clientY-touchButton.y)>8)touchButton=null;});
document.addEventListener('pointercancel',()=>{touchButton=null;});
document.addEventListener('pointerup',e=>{const tap=touchButton;touchButton=null;if(!tap||tap.id!==e.pointerId||!tap.button.isConnected||tap.button.disabled||e.target.closest('button[data-act]')!==tap.button)return;action(tap.button);});
document.addEventListener('keydown',e=>{if(e.repeat)return;suppressClickUntil=0;if(e.target.matches('input,textarea,select')||e.ctrlKey||e.metaKey||e.altKey)return;if(e.key==='Escape'){if($('dialog').open)return;cancelDeployment();selected=null;if(screen!=='battle'&&screen!=='home')showScreen('home');else render();return;}if($('dialog').open||screen!=='battle')return;if(interaction.mode==='direction'){const d={ArrowRight:0,ArrowDown:1,ArrowLeft:2,ArrowUp:3}[e.key];if(d!==undefined){e.preventDefault();interaction.setDirection(d);renderDeployment();}else if(e.key==='Enter'){e.preventDefault();confirmDeployment();}return;}
 if(e.target===canvas&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Enter'].includes(e.key)){e.preventDefault();if(e.key==='Enter'){if(selected)commitDeployment(selected,keyboardCell.x,keyboardCell.y);else{const u=game.s.units.find(u=>u.x===keyboardCell.x&&u.y===keyboardCell.y);if(u)setSelected(u.uid);}}else{keyboardCell.x=Math.max(0,Math.min(10,keyboardCell.x+(e.key==='ArrowRight'?1:e.key==='ArrowLeft'?-1:0)));keyboardCell.y=Math.max(0,Math.min(6,keyboardCell.y+(e.key==='ArrowDown'?1:e.key==='ArrowUp'?-1:0)));field.hover={...keyboardCell};}return;}
 if(e.code==='Space'&&e.target.tagName!=='BUTTON'){e.preventDefault();if(game.s.phase==='battle'){paused=!paused;renderBoardUI();renderIntel();}else if(game.s.phase==='prep')action({dataset:{act:'start'}});else if(game.s.phase==='intermission')send('next');}
 if(e.key.toLowerCase()==='r')send('refresh');if(e.key.toLowerCase()==='e')send('upgrade');if(e.key.toLowerCase()==='q')send('turn',selected,((game.s.units.find(u=>u.uid===selected)?.dir||0)+1)%4);if(e.key==='Delete'&&selected)send('sell',selected);
});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&screen==='battle'&&suspensionExpiresAt!==null){if(Date.now()>=suspensionExpiresAt){showScreen('home');toast('暂离存档已超过24小时，请开始新的模拟。');}else{suspensionExpiresAt=null;save();}}if(document.hidden){if(['prep','battle','intermission'].includes(game.s.phase))suspensionExpiresAt??=Date.now()+86400000;save();if(game.s.phase==='battle'){paused=true;renderBoardUI();renderIntel();}}});
window.addEventListener('beforeunload',()=>{if(['prep','battle','intermission'].includes(game.s.phase))suspensionExpiresAt??=Date.now()+86400000;save();});
let last=performance.now(),accum=0,uiTime=0,saveTime=0;
function frame(now){let realDt=Math.min(.15,(now-last)/1000);last=now;const running=game.s.phase==='battle'&&!paused&&screen==='battle'&&!document.hidden;
 if(running){accum+=realDt*speed;while(accum>=1/30&&game.s.phase==='battle'){session.advance(1/30);accum-=1/30;}uiTime+=realDt;saveTime+=realDt;if(uiTime>.25){renderStats();renderSelected();renderAlliances();uiTime=0;}if(saveTime>2){save();saveTime=0;}}
 else accum=0;field.draw(running?realDt*speed:realDt*.5);requestAnimationFrame(frame);
}
render();showScreen('home');requestAnimationFrame(frame);
window.__garrisonApp={get session(){return session;},get screen(){return screen;},get interaction(){return interaction;},boardPoint(x,y){const r=canvas.getBoundingClientRect(),p=field.point(x,y);return {x:r.left+p.x,y:r.top+p.y};},showScreen};
window.__garrisonReady=true;
clearTimeout(window.__garrisonBootTimer);
$('boot-screen')?.remove();
if(expiredSave)toast('上次暂离已超过24小时，原始记录已保留。');
if(incompatibleSave)toast('此版本无法恢复旧存档，原始数据已另行保留。');
if(game.s.phase==='battle')toast('已恢复上次对局。点击「继续作战」接着游玩。');
